// Bundles the report page's script (src/report/client.ts and the core it imports) into
// src/core/reportClient.generated.ts, a string the core's renderReport puts in the page. The page therefore
// needs nothing beside it: one HTML file.
//
//   node scripts/build-report.mjs          write the generated file
//   node scripts/build-report.mjs --check  exit 1 if it is out of date (CI runs this)
//
// esbuild is pinned so the output is the same on every machine.

import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ESBUILD = 'esbuild@0.25.5'
const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const out = join(root, 'src', 'core', 'reportClient.generated.ts')
const lf = text => text.replace(/\r\n/g, '\n')

const js = execFileSync(
  process.platform === 'win32' ? 'npx.cmd' : 'npx',
  ['--yes', ESBUILD, 'src/report/client.ts', '--bundle', '--minify', '--format=iife', '--target=es2022', '--log-level=error'],
  { cwd: root, encoding: 'utf8', shell: process.platform === 'win32', maxBuffer: 16 * 1024 * 1024 },
).trim()

const text = `// GENERATED by scripts/build-report.mjs from src/report/client.ts (and the core it imports). Do not edit by
// hand: change the page's script and run \`node scripts/build-report.mjs\`. CI fails if this is out of date.

export const REPORT_CLIENT_JS: string = ${JSON.stringify(js)}
`

if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = lf(readFileSync(out, 'utf8'))
  } catch {
    // missing counts as out of date
  }
  if (current !== text) {
    console.error('src/core/reportClient.generated.ts is out of date. Run: node scripts/build-report.mjs')
    process.exit(1)
  }
  console.log('src/core/reportClient.generated.ts is up to date.')
} else {
  writeFileSync(out, text)
  console.log(`wrote ${out} (${Math.round(js.length / 1024)} KB of script)`)
}
